CREATE TABLE IF NOT EXISTS property_intelligence.contractor_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contractor_id uuid NOT NULL REFERENCES property_intelligence.contractors(id) ON DELETE CASCADE, title varchar(150) NOT NULL, society_name varchar(150), city varchar(100), plot_size varchar(50), completed_year int, description text, photos jsonb NOT NULL DEFAULT '[]'::jsonb, status varchar(20) NOT NULL DEFAULT 'PENDING_REVIEW', source varchar(12) NOT NULL DEFAULT 'ADMIN', trust_tag varchar(20) NOT NULL DEFAULT 'ADMIN_ENTERED', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT contractor_projects_status_check CHECK (status IN ('PENDING_REVIEW','PUBLISHED','REJECTED')))
CREATE INDEX IF NOT EXISTS idx_contractor_projects_contractor_id ON property_intelligence.contractor_projects (contractor_id)
CREATE TABLE IF NOT EXISTS property_intelligence.contractor_upload_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contractor_id uuid NOT NULL REFERENCES property_intelligence.contractors(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz)
SELECT table_name FROM information_schema.tables WHERE table_schema = 'property_intelligence' AND table_name IN ('contractor_projects','contractor_upload_links')
